/**
 * PlanDetail Relation Options API Route
 * Generated by enhanced entity generator script V3 (configurable)
 */

import { auth } from '@clerk/nextjs/server';
import { asc, isNotNull } from 'drizzle-orm';
import { NextResponse } from 'next/server';

import { db } from '@/libs/DB';
import { planSchema, productSchema, productSubSchema, workTableSchema } from '@/models/Schema';

// GET /api/plandetails/relations/options
export async function GET() {
  try {
    const { userId } = await auth();
    if (!userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // Get plans
    const planOptions = await db.select({
      id: planSchema.id,
      planCode: planSchema.planCode,
    }).from(planSchema).orderBy(asc(planSchema.planCode));

    // Get products
    const productOptions = await db.select({
      id: productSchema.id,
      productCode: productSchema.productCode,
      productName: productSchema.productName,
    }).from(productSchema).orderBy(asc(productSchema.productCode));

    // Get location codes from work tables
    const locationOptions = await db.select({
      locationCode: workTableSchema.locationCode,
      tableName: workTableSchema.tableName,
    }).from(workTableSchema)
      .where(isNotNull(workTableSchema.locationCode))
      .orderBy(asc(workTableSchema.locationCode));

    // Remove duplicates manually
    type LocationItem = { locationCode: string | null; tableName: string | null };
    const uniqueLocationMap = new Map<string, LocationItem>();
    (locationOptions as LocationItem[]).forEach(item => {
      if (item.locationCode && !uniqueLocationMap.has(item.locationCode)) {
        uniqueLocationMap.set(item.locationCode, item);
      }
    });
    const filteredLocationOptions = Array.from(uniqueLocationMap.values());

    // Get product sub codes
    const productSubOptions = await db.select({
      productSubCode: productSubSchema.productSubCode,
      productSubDetail: productSubSchema.productSubDetail,
      productCode: productSubSchema.productCode,
    }).from(productSubSchema).orderBy(asc(productSubSchema.productSubCode));

    const relationOptions = {
      plans: planOptions,
      products: productOptions,
      locationCodes: filteredLocationOptions,
      productSubCodes: productSubOptions,
    };

    return NextResponse.json({
      success: true,
      data: relationOptions,
    });
  } catch (error) {
    console.error('Error fetching relation options:', error);
    return NextResponse.json(
      { error: 'Failed to fetch relation options' },
      { status: 500 },
    );
  }
}
